import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const base = dirname(fileURLToPath(import.meta.url));
const read = (relative) => readFile(resolve(base, relative), 'utf8');
const removeImports = (source) => source.replace(/^import\b[\s\S]*?;\r?\n/gm, '');
const common = await read('functions/username-login/helpers.ts');
const bodyLimit = common.match(/^export const MAX_REQUEST_BYTES = .+;$/m)?.[0];
const sharedStart = common.indexOf('export function allowedOrigins(');
const sharedEnd = common.indexOf('export async function privateHash(');
if (!bodyLimit || sharedStart < 0 || sharedEnd <= sharedStart) {
  throw new Error('Shared helper structure changed; review the admin dashboard bundle.');
}
const helpers = removeImports(await read('functions/account-admin/helpers.ts')).replace(
  /^export \{ readBoundedJson, responseHeaders \};\r?\n/m,
  '',
);
const handler = removeImports(await read('functions/account-admin/handler.ts'));
const index = removeImports(await read('functions/account-admin/index.ts'));
const bundle = [
  '// Single-file copy for Supabase Dashboard > Edge Functions > Editor.',
  '// Generated by: node supabase/build-account-admin-bundle.mjs',
  '// Source: functions/account-admin/{helpers,handler,index}.ts and shared CORS/body helpers.',
  '// Keep gateway Verify JWT OFF: this handler validates a fresh user token with Auth,',
  '// then checks the active administrator role in service-only SQL for every action.',
  '// Configure ALLOWED_ORIGINS with the exact website origin.',
  "import { createClient, isAuthApiError } from 'npm:@supabase/supabase-js@2.117.2';",
  '',
  bodyLimit,
  '',
  common.slice(sharedStart, sharedEnd).trim(),
  '',
  helpers.trim(),
  '',
  handler.trim(),
  '',
  index.trim(),
  '',
].join('\n');
await writeFile(resolve(base, 'dashboard-account-admin.ts'), bundle);
console.log('Generated supabase/dashboard-account-admin.ts');
